}

/* 顶掉酒馆自带的背景（#bg_custom 是用户自己设的图，一并统一，避免两张图打架） */
#bg1,
#bg_custom {
    position: fixed;
    inset: 0;
    width: 100% !important;
    height: 100% !important;
    background-color: var(--bl-bg-sky) !important;
    background-image: var(--bl-bg-photo) !important;
    background-repeat: no-repeat !important;
    background-position: left bottom !important;
    background-size: auto 100% !important;
    background-attachment: scroll !important;
    filter: none !important;
}

/* 视口比插画更瘦（手机竖屏）：改成裁切铺满，保住左边的人物和沙滩 */
@media (max-aspect-ratio: 59/100) {
    #bg1,
    #bg_custom {
        background-size: cover !important;
        background-position: left bottom !important;
    }
}

/* 超宽屏：插画略微放大，不然只剩细细一条 */
@media (min-width: 1600px) and (min-aspect-ratio: 16/10) {
    #bg1,
    #bg_custom {
        background-size: auto 125% !important;
    }
}

/* 宽屏时让插画右缘淡出到同色底，避免一条生硬的分界线 */
@media (min-width: 900px) {
    #bg1::before {
        content: "";
        position: absolute;
        inset: 0;
        background-image: linear-gradient(90deg, transparent 55%, var(--bl-bg-sky) 92%);
        pointer-events: none;
    }
}

/* 水光：很慢的漂移，给静态插画一点呼吸感 */
#bg1::after {
    content: "";
    position: absolute;
    inset: -15%;
    background-image:
        linear-gradient(180deg, rgba(255, 255, 255, 0.55), rgba(255, 255, 255, 0) 42%),
        radial-gradient(38% 32% at 26% 28%, rgba(255, 255, 255, 0.5), transparent 70%),
        radial-gradient(30% 26% at 70% 62%, rgba(186, 232, 255, 0.3), transparent 72%);
    animation: bl-bg-shine 28s ease-in-out infinite alternate;
    pointer-events: none;
}

@keyframes bl-bg-shine {
    from {
        transform: translate3d(-2%, -1%, 0) scale(1.02);
        opacity: 0.5;
    }

    to {
        transform: translate3d(3%, 2%, 0) scale(1.06);
        opacity: 0.85;
    }
}

@media (prefers-reduced-motion: reduce) {
    #bg1::after {
        animation: none;
    }
}


/*
 * bilibili 官方图标字体 bcc-iconfont（旧版专栏 / 评论区专用字形）
 * 数据来源：本地保存的 bilibili 页面快照 iconfont.css 中内嵌的 woff2。
 * 本文件由 tools/extract-assets.cjs 生成，请勿手改。
 */

@font-face {
    font-family: "bcc-iconfont";
    src: url("data:application/x-font-woff2;charset=utf-8;base64,") format("woff2");
    font-weight: normal;
    font-style: normal;
    font-display: swap;
}

/* 用法：给元素加 .bl-ic 与 .bl-ic--xxx，伪元素即显示对应图标 */
.bl-ic::before {
    font-family: "bcc-iconfont" !important;
    font-style: normal;
    font-weight: normal;
    line-height: 1;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

.bl-ic--play::before { content: "\e690"; } /* 播放 */
.bl-ic--danmaku::before { content: "\e691"; } /* 弹幕 */
.bl-ic--like::before { content: "\e692"; } /* 点赞 */
.bl-ic--coin::before { content: "\e693"; } /* 投币 */
.bl-ic--share::before { content: "\e695"; } /* 分享 */
.bl-ic--comment::before { content: "\e696"; } /* 评论 */
.bl-ic--fav::before { content: "\e697"; } /* 收藏 */
.bl-ic--reward::before { content: "\e69e"; } /* 打赏 */
.bl-ic--time::before { content: "\e6a0"; } /* 时间 */
.bl-ic--warning::before { content: "\e69f"; } /* 警告 */
.bl-ic--success::before { content: "\e67d"; } /* 成功 */
.bl-ic--info::before { content: "\e67c"; } /* 提示 */
.bl-ic--more::before { content: "\e698"; } /* 更多 */
.bl-ic--sort::before { content: "\e682"; } /* 排序 */


/*
 * bilibili 官网图标字体 vanfont（三连图标专用）
 * 来源：github.com/dashuchufang/bili_icon_pack 的 vanfont.woff（直接提取自 bilibili 网页）
 * 码点：赞 \e6e0 / 收藏 \e6e1 / 投币 \e6e4 / 分享 \e70f
 */

@font-face {
    font-family: "bl-vanfont";
    src: url("data:font/woff;base64,") format("woff");
    font-display: block;
}


/*
 * 默认头像：酒馆在「角色未设头像」时使用 img/ai4.png（用户用 user-default.png），
 * 那是一张黑色剪影加问号。这里用 content 把 <img> 的显示内容换成主题自带的图，
 * 不改酒馆本体文件，也不影响任何已经设了自定义头像的角色。
 *
 * src 用包含匹配，覆盖 img/ai4.png、/img/ai4.png、缩略图 404 后回退等各种写法。
 */
img[src*="ai4.png"],
img[src*="user-default.png"] {
    content: var(--bl-avatar-default);
}

/* 少数地方把默认头像写成容器的内联背景图，一并覆盖 */
.avatar[style*="ai4.png"],
.avatar[style*="user-default.png"] {
    background-image: var(--bl-avatar-default) !important;
    background-size: cover;
    background-position: center;
}


/*
 * 框架层：全局底色与字体、顶栏、左右侧栏、分区标题、滚动条
 * 目标观感：白色顶栏 + 1px 细线 + 浅灰页面底，纯平面、零毛玻璃。
 */

/* ---------- 全局 ---------- */
body {
    font-family: var(--bl-font) !important;
    background-color: var(--bl-bg-sky) !important;
    background-image: none !important;
    color: var(--bl-text-1);
    letter-spacing: 0;
    -webkit-font-smoothing: antialiased;
}

textarea,
input,
select,
pre,
code,
.edit_textarea {
    font-family: var(--bl-font);
}

::selection {
    background: var(--bl-pink-soft);
    color: var(--bl-pink);
}

/* ---------- 顶栏 ---------- */
#top-bar,
#top-settings-holder {
    background-color: var(--bl-bg-1);
    border-bottom: 1px solid var(--bl-line);
    box-shadow: none;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    color: var(--bl-text-2);
}

/* 顶栏宽度交回酒馆的「页面宽度」设置，不再额外夹窄 */
#top-bar,
#top-settings-holder {
    /* 面板顶部两角跟中间列一起收圆，底部两角由输入区收口 */
    border-radius: 12px 12px 0 0;
}

#top-settings-holder {
    position: relative;
    align-items: center;
    /* 左侧给 logo 让位，右侧给「投稿」按钮让位，否则会压住顶栏图标 */
    padding: 0 118px 0 132px;
}

/* 左上角：矢量小电视（代码绘制）+ bilibili 字标（矢量），两者都改品牌粉 */
#top-settings-holder::before {
    content: "";
    position: absolute;
    left: 18px;
    top: 50%;
    transform: translateY(-50%);
    width: 96px;
    height: 32px;
    background-image: var(--bl-tv), var(--bl-wordmark);
    background-repeat: no-repeat, no-repeat;
    background-position: left center, 38px center;
    background-size: auto 28px, auto 24px;
    pointer-events: none;
}

/*
 * 右上角「投稿」：直接复用酒馆原生的「角色管理」按钮（#rightNavDrawerIcon），
 * 只把它换个皮。这样整块都能点，且点了就是原来的打开角色管理面板，功能不丢。
 */
#rightNavHolder > .drawer-toggle {
    position: absolute;
    right: 18px;
    top: 50%;
    transform: translateY(-50%);
    display: block;
}

#rightNavDrawerIcon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: auto;
    height: 32px;
    padding: 0 18px;
    background-color: var(--bl-pink);
    color: #FFFFFF;
    opacity: 1;
    border-radius: var(--bl-radius);
    box-shadow: 0 1px 4px rgba(251, 114, 153, 0.3);
    cursor: pointer;
    user-select: none;
    transition: background-color 0.15s ease, transform 0.15s ease, box-shadow 0.15s ease;
}

/* 去掉 FontAwesome 的角色卡片字形，换成「投稿」两个字 */
#rightNavDrawerIcon::before {
    content: none;
}

#rightNavDrawerIcon::after {
    content: "投稿";
    font-family: var(--bl-font);
    font-size: 14px;
    font-weight: 500;
    letter-spacing: 1px;
}

#rightNavDrawerIcon:hover {
    background-color: var(--bl-pink-hover);
    color: #FFFFFF;
    opacity: 1;
}

#rightNavDrawerIcon:active {
    transform: scale(0.96);
    box-shadow: 0 1px 2px rgba(251, 114, 153, 0.25);
}

/* 顶栏图标：默认 0.3 透明度在浅色底上几乎看不见，这里提到 0.8 */
.drawer-icon.closedIcon,
.drawer-icon.openIcon {
    color: var(--bl-text-2);
    opacity: 0.8;
    border-radius: var(--bl-radius-sm);
    transition: background-color var(--bl-ease), color var(--bl-ease), opacity var(--bl-ease);
}

.drawer-icon.closedIcon:hover {
    color: var(--bl-text-1);
    opacity: 1;
    background-color: var(--bl-bg-3);
}

.drawer-icon.openIcon {
    color: var(--bl-pink);
    opacity: 1;
    background-color: var(--bl-pink-soft);
}

/* 顶栏右侧的角色快捷切换条 */
.hotswap,
.hotswap.closedIcon {
    color: var(--bl-text-2);
    opacity: 0.8;
}

.hotswap:hover {
    color: var(--bl-pink);
    opacity: 1;
}

/* ---------- 左右侧栏 / 抽屉 ---------- */
#left-nav-panel,
#right-nav-panel {
    background-color: var(--bl-bg-1);
    border-color: var(--bl-line);
    box-shadow: var(--bl-shadow-float);
}

#left-nav-panel .drawer-content,
#right-nav-panel .drawer-content {
    background-color: var(--bl-bg-1);
}

/* 聊天主列：宽度、位置全部交给酒馆的「页面宽度」参数，主题不再插手 */
#sheld {
    background-color: transparent;
    border: none;
}

.drawer-content {
    background-color: var(--bl-bg-1);
    border-color: var(--bl-line);
    color: var(--bl-text-1);
    /* 宽度不覆盖：跟随酒馆「页面宽度」参数（--sheldWidth），与主体天然同宽 */
}

/* B 站侧栏分组标题：粉色竖条 + 深色加粗 */
.standoutHeader {
    position: relative;
    color: var(--bl-text-1);
    font-weight: 600;
    border-bottom: none;
    padding-left: 10px;
    margin-bottom: 6px;
}

.standoutHeader::before {
    content: "";
    position: absolute;
    left: 0;
    top: 50%;
    width: 3px;
    height: 0.95em;
    transform: translateY(-50%);
    background-color: var(--bl-pink);
    border-radius: 2px;
}

/* 折叠抽屉标题 */
.inline-drawer-header,
.inline-drawer-toggle.inline-drawer-header {
    color: var(--bl-text-1);
    font-weight: 600;
    border-radius: var(--bl-radius-sm);
    transition: background-color var(--bl-ease);
}

.inline-drawer-header:hover,
.inline-drawer-toggle.inline-drawer-header:hover {
    background-color: var(--bl-pink-soft);
    color: var(--bl-pink);
}

.inline-drawer-icon {
    color: var(--bl-text-3);
}

/* ---------- 滚动条 ---------- */
::-webkit-scrollbar {
    width: 8px;
    height: 8px;
}

::-webkit-scrollbar-track {
    background: transparent;
}

::-webkit-scrollbar-thumb {
    background-color: #D8DBDF;
    border-radius: var(--bl-radius-pill);
}

::-webkit-scrollbar-thumb:hover {
    background-color: #C4C8CD;
}

/* ---------- 聊天区容器 ---------- */
#chat {
    background-color: var(--bl-bg-2);
    /* 左右不留白：卡片宽度 = 页面宽度参数，和顶栏、抽屉、输入区完全等宽 */
    padding: 6px 0 8px;
}


/*
 * 内容层（上）：AI 消息 = bilibili 专栏文章
 * 白卡 + 1px 细边框，大号标题、作者行、17px 正文，底部一排原版三连图标。
 */

/* ---------- 专栏卡片 ---------- */
#chat .mes[is_user="false"] {
    display: flex;
    align-items: flex-start;
    gap: 14px;
    width: 100%;
    align-self: center;
    margin: 0 auto var(--bl-chat-gap);
    padding: 22px 26px 10px;
    background-color: var(--bl-bg-1);
    border: 1px solid var(--bl-line);
    border-radius: var(--bl-radius);
    box-shadow: var(--bl-shadow-card);
}

/* 左侧作者头像 */
#chat .mes[is_user="false"] .mesAvatarWrapper {
    flex: 0 0 var(--bl-avatar-size);
    width: var(--bl-avatar-size);
}

#chat .mes[is_user="false"] .mesAvatarWrapper .avatar {
    width: var(--bl-avatar-size);
    height: var(--bl-avatar-size);
    border-radius: 50%;
    overflow: hidden;
    border: none;
    box-shadow: none;
    cursor: pointer;
    transition: transform var(--bl-ease);
}

#chat .mes[is_user="false"] .mesAvatarWrapper .avatar:hover {
    transform: scale(1.04);
}

/*
 * 酒馆默认把 .avatar img 写死成 50×50，还自带边框、投影和 50% 圆角；
 * 主题把容器缩成 44px / 36px 后，那张 50px 的圆图被容器裁掉一角，
 * 头像看起来就成了「不圆的圆」。这里让图片填满容器，裁切统一交给 .avatar。
 */
#chat .mes .mesAvatarWrapper .avatar img {
    display: block;
    width: 100%;
    height: 100%;
    border: none;
    border-radius: 50%;
    box-shadow: none;
    object-fit: cover;
    object-position: center;
}

#chat .mes[is_user="false"] .mes_block {
    flex: 1 1 auto;
    min-width: 0;
    /* 抵消酒馆 .mes_block 自带的 padding-left: 10px，让正文左右对称 */
    padding-right: 10px;
}

/*
 * 左侧有「头像 + 间距」一整列，右侧原本什么都没有，正文看着就偏右。
 * 用一个透明伪元素在右侧补等宽占位，正文便在卡片内左右居中。
 */
#chat .mes[is_user="false"]::after {
    content: "";
    /* +14px：酒馆在头像前还塞了一个 0 宽的消息复选框，会多吃一份 flex gap */
    flex: 0 0 calc(var(--bl-avatar-size) + 14px);
    align-self: flex-start;
}

/* ---------- 标题行（角色名 = 专栏标题） ---------- */
#chat .mes[is_user="false"] .ch_name {
    align-items: flex-start;
    gap: 8px;
    margin-bottom: 6px;
    border-bottom: none;
}

#chat .mes[is_user="false"] .name_text {
    font-size: var(--bl-title-size);
    font-weight: 600;
    line-height: 1.35;
    color: var(--bl-text-1);
    letter-spacing: 0.2px;
    word-break: break-word;
}

#chat .mes .timestamp {
    margin-left: 8px;
    font-size: 12.5px;
    color: var(--bl-text-3);
    font-variant-numeric: tabular-nums;
}

#chat .mes .mesIDDisplay,
#chat .mes .tokenCounterDisplay,
#chat .mes .mes_timer {
    color: var(--bl-text-3);
    font-size: 11px;
}

/* ---------- 正文排版 ---------- */
#chat .mes[is_user="false"] .mes_text {
    font-size: var(--bl-body-size);
    line-height: var(--bl-body-line);
    color: var(--bl-text-1);
    padding: 2px 0 4px;
    word-break: break-word;
    overflow-wrap: anywhere;
}

#chat .mes_text p {
    margin: 0 0 0.85em;
}

#chat .mes_text p:last-child {
    margin-bottom: 0;
}

#chat .mes_text strong,
#chat .mes_text b {
    font-weight: 600;
    color: var(--bl-text-1);
}

#chat .mes_text em,
#chat .mes_text i {
    color: var(--bl-text-2);
}

#chat .mes_text a {
    color: var(--bl-blue-deep);
    text-decoration: none;
    border-bottom: 1px solid rgba(0, 105, 157, 0.3);
    transition: color var(--bl-ease), border-color var(--bl-ease);
}

#chat .mes_text a:hover {
    color: var(--bl-blue);
    border-bottom-color: var(--bl-blue);
}

/* 标题层级：像专栏里的小标题 */
#chat .mes_text h1,
#chat .mes_text h2,
#chat .mes_text h3,
#chat .mes_text h4 {
    color: var(--bl-text-1);
    font-weight: 600;
    line-height: 1.5;
    margin: 1.4em 0 0.6em;
}

#chat .mes_text h1 { font-size: 1.35em; }
#chat .mes_text h2 { font-size: 1.2em; }
#chat .mes_text h3 { font-size: 1.08em; }

#chat .mes_text h1:first-child,
#chat .mes_text h2:first-child,
#chat .mes_text h3:first-child {
    margin-top: 0;
}

/* 引用：粉色左竖线 + 浅灰底 */
#chat .mes_text blockquote {
    margin: 0 0 0.9em;
    padding: 10px 14px;
    background-color: var(--bl-bg-2);
    border-left: 3px solid var(--bl-pink);
    border-radius: 0 var(--bl-radius-sm) var(--bl-radius-sm) 0;
    color: var(--bl-text-2);
}

#chat .mes_text blockquote p:last-child {
    margin-bottom: 0;
}

/* 列表 */
#chat .mes_text ul,
#chat .mes_text ol {
    margin: 0 0 0.9em;
    padding-left: 1.4em;
}

#chat .mes_text li {
    margin-bottom: 0.3em;
}

#chat .mes_text li::marker {
    color: var(--bl-pink);
}

/* 行内代码 */
#chat .mes_text code {
    padding: 2px 5px;
    border-radius: 4px;
    background-color: var(--bl-bg-3);
    color: #D14F79;
    font-family: var(--bl-font-mono);
    font-size: 0.9em;
}

/* 代码块：浅灰卡片，标题栏感 */
#chat .mes_text pre {
    margin: 0 0 0.9em;
    padding: 12px 14px;
    background-color: var(--bl-bg-2);
    border: 1px solid var(--bl-line);
    border-radius: var(--bl-radius-sm);
    overflow-x: auto;
}

#chat .mes_text pre code {
    padding: 0;
    background: transparent;
    color: var(--bl-text-1);
    font-size: 13px;
    line-height: 1.7;
}

/* 分割线 */
#chat .mes_text hr {
    height: 1px;
    border: none;
    background-color: var(--bl-line);
    margin: 1.2em 0;
}

/* 表格 */
#chat .mes_text table {
    width: 100%;
    margin: 0 0 0.9em;
    border-collapse: collapse;
    font-size: 0.94em;
}

#chat .mes_text th,
#chat .mes_text td {
    padding: 8px 10px;
    border: 1px solid var(--bl-line);
    text-align: left;
}

#chat .mes_text th {
    background-color: var(--bl-bg-2);
    font-weight: 600;
}

/* ---------- 消息按钮（专栏右上角操作） ---------- */
#chat .mes .mes_button {
    color: var(--bl-text-3);
    opacity: 1;
    transition: color var(--bl-ease), background-color var(--bl-ease);
    border-radius: var(--bl-radius-sm);
}

#chat .mes .mes_button:hover {
    color: var(--bl-pink);
    background-color: var(--bl-pink-soft);
}

#chat .mes .mes_buttons {
    opacity: 0.45;
    transition: opacity var(--bl-ease);
}

#chat .mes:hover .mes_buttons {
    opacity: 1;
}

/* ---------- 底部三连操作行（官网 vanfont 图标：赞 / 币 / 藏 / 分享） ---------- */
#chat .mes[is_user="false"] .mes_block::after {
    content: "\e6e0\00a0\00a0\00a0\e6e4\00a0\00a0\00a0\e6e1\00a0\00a0\00a0\e70f";
    display: block;
    margin-top: 12px;
    padding-top: 10px;
    border-top: 1px solid var(--bl-line-soft);
    font-family: "bl-vanfont" !important;
    font-size: 17px;
    line-height: 1;
    color: var(--bl-text-3);
    letter-spacing: 1px;
    user-select: none;
}

/* ---------- 推理块（思考过程） ---------- */
#chat .mes_reasoning_details {
    margin: 0 0 10px;
    padding: 8px 12px;
    background-color: var(--bl-bg-2);
    border: 1px solid var(--bl-line);
    border-radius: var(--bl-radius-sm);
}

#chat .mes_reasoning_header,
#chat .mes_reasoning_header_title {
    color: var(--bl-text-2);
    font-size: 13px;
}

#chat .mes_reasoning {
    color: var(--bl-text-2);
    font-size: 14px;
    line-height: 1.8;
}


/*
 * 内容层（下）：用户消息 = bilibili 评论区的一条评论
 * 浅灰块 + 圆形头像 + 蓝色昵称 + 灰色时间，正文 15px，底部点赞/回复图标行。
 */

#chat .mes[is_user="true"] {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    width: 100%;
    align-self: center;
    margin: 0 auto 10px;
    padding: 14px 18px 10px;
    background-color: var(--bl-bg-3);
    border: 1px solid transparent;
    border-radius: var(--bl-radius);
    box-shadow: none;
    transition: background-color var(--bl-ease), border-color var(--bl-ease);
}

#chat .mes[is_user="true"]:hover {
    background-color: #EDEFF1;
    border-color: var(--bl-line);
}

/* 评论者头像 */
#chat .mes[is_user="true"] .mesAvatarWrapper {
    flex: 0 0 36px;
    width: 36px;
}

#chat .mes[is_user="true"] .mesAvatarWrapper .avatar {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    overflow: hidden;
    border: none;
    box-shadow: none;
}

#chat .mes[is_user="true"] .mes_block {
    flex: 1 1 auto;
    min-width: 0;
    /* 抵消酒馆 .mes_block 自带的 padding-left: 10px，让正文左右对称 */
    padding-right: 10px;
}

/* 与 AI 消息同理：右侧补一列和头像等宽的透明占位 */
#chat .mes[is_user="true"]::after {
    content: "";
    /* 36px 头像 + 14px：抵消左侧消息复选框多吃的一份 flex gap */
    flex: 0 0 50px;
    align-self: flex-start;
}

/* 昵称 + 时间 */
#chat .mes[is_user="true"] .ch_name {
    align-items: center;
    margin-bottom: 2px;
}

#chat .mes[is_user="true"] .name_text {
    font-size: 14px;
    font-weight: 600;
    color: var(--bl-blue-deep);
    line-height: 1.5;
}

#chat .mes[is_user="true"] .timestamp {
    font-size: 12px;
    color: var(--bl-text-3);
    margin-left: 8px;
}

/* 评论正文 */
#chat .mes[is_user="true"] .mes_text {
    font-size: var(--bl-comment-size);
    line-height: 1.75;
    color: var(--bl-text-1);
    padding: 2px 0 0;
    word-break: break-word;
    overflow-wrap: anywhere;
}

#chat .mes[is_user="true"] .mes_text p {
    margin: 0 0 0.6em;
}

#chat .mes[is_user="true"] .mes_text p:last-child {
    margin-bottom: 0;
}

#chat .mes[is_user="true"] .mes_text blockquote {
    margin: 0 0 0.6em;
    padding: 6px 10px;
    background-color: rgba(255, 255, 255, 0.75);
    border-left: 3px solid var(--bl-blue);
    border-radius: 0 4px 4px 0;
    color: var(--bl-text-2);
}

#chat .mes[is_user="true"] .mes_text code {
    padding: 1px 4px;
    border-radius: 4px;
    background-color: rgba(0, 0, 0, 0.05);
    color: #D14F79;
    font-family: var(--bl-font-mono);
    font-size: 0.9em;
}

#chat .mes[is_user="true"] .mes_text pre {
    margin: 0 0 0.6em;
    padding: 10px 12px;
    background-color: var(--bl-bg-1);
    border: 1px solid var(--bl-line);
    border-radius: var(--bl-radius-sm);
    overflow-x: auto;
}

#chat .mes[is_user="true"] .mes_text pre code {
    background: transparent;
    padding: 0;
    color: var(--bl-text-1);
}

#chat .mes[is_user="true"] .mes_text a {
    color: var(--bl-blue-deep);
    text-decoration: none;
}

#chat .mes[is_user="true"] .mes_text a:hover {
    color: var(--bl-blue);
}

/* 评论底部：点赞 / 回复（原版图标，纯装饰） */
#chat .mes[is_user="true"] .mes_block::after {
    content: "\e692\00a0\00a0\00a0\e696";
    display: block;
    margin-top: 8px;
    font-family: "bcc-iconfont" !important;
    font-size: 14px;
    line-height: 1;
    color: var(--bl-text-3);
    letter-spacing: 1px;
    user-select: none;
}

/* 右侧滑动切换块 */
#chat .mes .swipeRightBlock {
    color: var(--bl-text-3);
}

#chat .mes .swipe_left,
#chat .mes .swipe_right {
    color: var(--bl-text-3);
    transition: color var(--bl-ease);
}

#chat .mes .swipe_left:hover,
#chat .mes .swipe_right:hover {
    color: var(--bl-pink);
}

#chat .mes .swipes-counter {
    color: var(--bl-text-3);
    font-size: 11px;
}

/* 楼层里插入的图片 / 附件圆角化 */
#chat .mes_media_wrapper img,
#chat .mes_file_wrapper img {
    border-radius: var(--bl-radius-sm);
}


/*
 * 交互层（一）：输入区 = bilibili 评论区输入框
 * 白底圆角框 + 聚焦蓝描边 + 粉色圆形发送按钮。
 */

#form_sheld {
    background-color: var(--bl-bg-2);
    border-top: 1px solid var(--bl-line);
    padding: 6px var(--bl-gutter) 8px;
    /* 面板底部两角，和顶栏的圆角呼应 */
    border-radius: 0 0 12px 12px;
}

#nonQRFormItems {
    display: flex;
    align-items: center;
    gap: 4px;
    width: 100%;
    margin: 0 auto;
    padding: 3px 6px;
    background-color: var(--bl-bg-1);
    border: 1px solid var(--bl-line);
    border-radius: var(--bl-radius);
    transition: border-color var(--bl-ease), box-shadow var(--bl-ease);
}

#nonQRFormItems:focus-within {
    border-color: var(--bl-blue);
    box-shadow: 0 0 0 2px rgba(0, 174, 236, 0.14);
}

/* 输入框本体：默认只占一行，输入多行时由酒馆脚本自动撑高 */
#send_textarea {
    flex: 1 1 auto;
    min-width: 0;
    height: 24px;
    min-height: 24px;
    max-height: 40vh;
    padding: 2px 4px;
    margin: 0;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    color: var(--bl-text-1);
    font-size: 14.5px;
    line-height: 20px;
    text-align: left;
    resize: none;
    outline: none;
}

#send_textarea::placeholder {
    color: var(--bl-text-3);
}

/* 酒馆内建的输入框文字/占位符居中被后续样式表覆盖，这里提高特异性改回左对齐 */
#form_sheld #send_textarea,
#form_sheld #send_textarea::placeholder {
    text-align: left;
}

/* 左侧多功能按钮 */
/* 左右按钮组横向排列，避免两个圆形按钮上下叠把输入框撑成两行高 */
#leftSendForm,
#rightSendForm {
    display: flex;
    flex-direction: row;
    flex-wrap: nowrap;
    flex: 0 0 auto;
    width: max-content;
    min-width: 0;
    align-items: center;
    gap: 3px;
}

#options_button,
#leftSendForm .interactable {
    display: flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    width: 27px;
    height: 27px;
    min-width: 27px;
    padding: 0;
    border-radius: var(--bl-radius-sm);
    color: var(--bl-text-3);
    font-size: 14px;
    line-height: 1;
    transition: background-color var(--bl-ease), color var(--bl-ease);
}

#options_button:hover,
#leftSendForm .interactable:hover {
    background-color: var(--bl-bg-3);
    color: var(--bl-pink);
}

/* 发送按钮：粉色胶囊 */
#send_but:not(.displayNone) {
    display: flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    width: 28px;
    height: 28px;
    min-width: 28px;
    padding: 0;
    border: none;
    border-radius: var(--bl-radius-pill);
    background-color: var(--bl-pink);
    color: #FFFFFF;
    font-size: 12px;
    line-height: 1;
    cursor: pointer;
    box-shadow: none;
    transition: background-color var(--bl-ease), transform var(--bl-ease), filter var(--bl-ease);
}

/* 停止 / 继续 / 扮演：只改外观，不碰 display —— 显隐由酒馆自己控制，
   停止按钮只在生成回复时顶替发送按钮出现 */
#mes_stop,
#mes_continue,
#mes_impersonate,
#stscript_stop,
#stscript_continue,
#stscript_pause {
    box-sizing: border-box;
    width: 28px;
    height: 28px;
    min-width: 28px;
    padding: 0;
    border: none;
    border-radius: var(--bl-radius-pill);
    background-color: var(--bl-pink);
    color: #FFFFFF;
    font-size: 12px;
    line-height: 1;
    cursor: pointer;
    box-shadow: none;
    transition: background-color var(--bl-ease), transform var(--bl-ease), filter var(--bl-ease);
}

#send_but:not(.displayNone):hover,
#mes_stop:not(.displayNone):hover,
#mes_continue:not(.displayNone):hover,
#mes_impersonate:not(.displayNone):hover,
#stscript_stop:not(.displayNone):hover,
#stscript_continue:not(.displayNone):hover,
#stscript_pause:not(.displayNone):hover {
    background-color: var(--bl-pink-hover);
    transform: translateY(-1px);
}

/* 停止按钮只在生成期间出现，用深一档的粉色与发送按钮区分 */
#mes_stop {
    background-color: var(--bl-pink);
    animation: bl-pulse 1.6s ease-in-out infinite;
}

#mes_stop:hover {
    background-color: #E85B85;
}

/* 发送按钮用原版「播放」图标的感觉：纸飞机保留 FA，颜色统一粉色 */
#send_but::before {
    font-size: 14px;
}

/* ---------- 快捷回复（QR） ---------- */
#qr--bar {
    margin: 0 auto 6px;
    padding: 0;
    background: transparent;
    color: var(--bl-text-2);
}

/* quick-reply 扩展样式在本主题之后加载，统一用 #send_form 前缀提高特异性 */
/* 每个 QR 分组各自是一个 .qr--buttons，只让分组宽度自适应，标签才能横向排开 */
#send_form #qr--bar {
    display: flex;
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: center;
    align-items: center;
    gap: 6px;
}

#form_sheld #qr--bar > .qr--buttons {
    flex: 0 0 auto;
    width: auto;
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: center;
    align-items: center;
    gap: 6px;
    padding: 0;
}

/* 注意：quick-reply 扩展的样式表在本主题之后加载，这里用 #form_sheld 提高特异性 */
#form_sheld #qr--bar > .qr--buttons .qr--button {
    max-width: 210px;
    padding: 3px 10px;
    background-color: var(--bl-bg-1);
    border: 1px solid var(--bl-line);
    border-radius: var(--bl-radius-pill);
    color: var(--bl-text-2);
    font-size: 12px;
    line-height: 1.5;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    transition: border-color var(--bl-ease), color var(--bl-ease), background-color var(--bl-ease);
}

#form_sheld #qr--bar > .qr--buttons .qr--button:hover {
    border-color: var(--bl-pink);
    background-color: var(--bl-pink-soft);
    color: var(--bl-pink);
}

body #qr--popout > .qr--body {
    background-color: var(--bl-bg-1);
    border: 1px solid var(--bl-line);
    border-radius: var(--bl-radius);
    box-shadow: var(--bl-shadow-float);
}

body #qr--popout > .qr--body > .qr--buttons .qr--button {
    max-width: 260px;
    padding: 4px 10px;
    background-color: var(--bl-bg-1);
    border: 1px solid var(--bl-line);
    border-radius: var(--bl-radius-sm);
    color: var(--bl-text-2);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

body #qr--popout > .qr--body > .qr--buttons .qr--button:hover {
    background-color: var(--bl-pink-soft);
    border-color: var(--bl-pink);
    color: var(--bl-pink);
}

/* 附件预览条 */
#file_form .file_attached {
    border-radius: var(--bl-radius-sm);
    background-color: var(--bl-bg-3);
    border: 1px solid var(--bl-line);
}

/* 打字指示器 / 加载提示 */
#typing_indicator {
    color: var(--bl-text-3);
    font-size: 12.5px;
}

#typing_indicator::before {
    content: "\e691";
    font-family: "bcc-iconfont" !important;
    margin-right: 4px;
    color: var(--bl-pink);
    font-size: 13px;
}

@keyframes bl-pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.6; }
}

@media (prefers-reduced-motion: reduce) {
    #mes_stop:not(.displayNone) {
        animation: none;
    }
}


/*
 * 交互层（二）：抽屉、设置面板、表单控件、菜单、提示
 * 统一成 bilibili 组件风：白底、1px 细线、6-8px 圆角、粉色强调。
 */

/* ---------- 面板与抽屉 ---------- */
.drawer-content,
#top-settings-holder .drawer-content,
#left-nav-panel .drawer-content,
#right-nav-panel .drawer-content {
    background-color: var(--bl-bg-1);
    border-color: var(--bl-line);
    color: var(--bl-text-1);
}

.drawer-content .scrollableInner,
#left-nav-panel .scrollableInner,
#right-nav-panel .scrollableInner {
    scrollbar-width: thin;
}

/* 面板内部分隔 */
#left-nav-panel hr,
#right-nav-panel hr,
.drawer-content hr {
    border: none;
    border-top: 1px solid var(--bl-line);
    margin: 10px 0;
}

/* ---------- 文本输入 ---------- */
.text_pole,
textarea.text_pole,
input.text_pole,
input[type="text"],
input[type="search"],
input[type="number"],
input[type="password"] {
    background-color: var(--bl-bg-1);
    border: 1px solid var(--bl-line);
    border-radius: var(--bl-radius-sm);
    color: var(--bl-text-1);
    transition: border-color var(--bl-ease), box-shadow var(--bl-ease);
}

.text_pole:focus,
textarea.text_pole:focus,
input[type="text"]:focus,
input[type="search"]:focus,
input[type="number"]:focus,
input[type="password"]:focus {
    outline: none;
    border-color: var(--bl-blue);
    box-shadow: 0 0 0 2px rgba(0, 174, 236, 0.13);
}

.text_pole::placeholder {
    color: var(--bl-text-3);
}

/* 下拉框 */
select,
.text_pole.select,
.select2-container--default .select2-selection--single,
.select2-container--default .select2-selection--multiple {
    background-color: var(--bl-bg-1);
    border: 1px solid var(--bl-line);
    border-radius: var(--bl-radius-sm);
    color: var(--bl-text-1);
}

.select2-container--default .select2-selection--single .select2-selection__rendered {
    color: var(--bl-text-1);
}

/* 原生下拉的选项默认是黑底白字（深色主题专用），白底主题里会突然黑一片 */
select option {
    background-color: var(--bl-bg-1);
    color: var(--bl-text-1);
}

select option:not(:checked) {
    background-color: var(--bl-bg-1);
    color: var(--bl-text-1);
}

select option:checked {
    background-color: var(--bl-pink-soft);
    color: var(--bl-text-1);
}

select option[disabled]:not(:checked) {
    color: var(--bl-text-3);
}

.select2-dropdown {
    background-color: var(--bl-bg-1);
    border: 1px solid var(--bl-line);
    border-radius: var(--bl-radius-sm);
    box-shadow: var(--bl-shadow-float);
}

.select2-container--default .select2-results__option--highlighted[aria-selected] {
    background-color: var(--bl-pink-soft);
    color: var(--bl-pink);
}

/* 勾选框 / 滑块 / 单选 */
input[type="checkbox"],
input[type="radio"] {
    accent-color: var(--bl-pink);
}

input[type="range"] {
    accent-color: var(--bl-pink);
}

/* ---------- 按钮 ---------- */
.menu_button,
.menu_button_icon {
    background-color: var(--bl-bg-1);
    border: 1px solid var(--bl-line);
    border-radius: var(--bl-radius-sm);
    color: var(--bl-text-2);
    transition: background-color var(--bl-ease), border-color var(--bl-ease), color var(--bl-ease);
}

.menu_button:hover,
.menu_button_icon:hover {
    background-color: var(--bl-pink-soft);
    border-color: var(--bl-pink);
    color: var(--bl-pink);
}

.menu_button.selected,
.menu_button.toggleEnabled {
    background-color: var(--bl-pink);
    border-color: var(--bl-pink);
    color: #FFFFFF;
}

/* 危险操作按钮保持红色语义 */
.menu_button.danger,
#delete_button:hover,
#reset_button:hover {
    color: #F56C6C;
}

/* ---------- 角色列表 / 卡片条目 ---------- */
.character_select,
.group_select,
.character_select_container,
.entity_block {
    border-radius: var(--bl-radius-sm);
    transition: background-color var(--bl-ease);
}

.character_select:hover,
.group_select:hover {
    background-color: var(--bl-bg-2);
}

.character_name_block .ch_name,
.character_name_block .character_name {
    color: var(--bl-text-1);
    font-weight: 600;
}

.character_name_block .character_file,
.character_name_block .group_file {
    color: var(--bl-text-3);
}

/* 当前选中角色 */
.character_select.is_selected,
.group_select.is_selected {
    background-color: var(--bl-pink-soft);
}

/* ---------- 弹出菜单 / 弹层 ---------- */
#options,
.options-content,
.popup,
.dialogs,
#dialogue_popup {
    background-color: var(--bl-bg-1);
    border: 1px solid var(--bl-line);
    border-radius: var(--bl-radius);
    box-shadow: var(--bl-shadow-float);
    color: var(--bl-text-1);
}

#options .options-content a,
#options .options-content .interactable {
    border-radius: var(--bl-radius-sm);
    transition: background-color var(--bl-ease), color var(--bl-ease);
}

#options .options-content a:hover,
#options .options-content .interactable:hover {
    background-color: var(--bl-pink-soft);
    color: var(--bl-pink);
}

/* 弹窗标题 */
.dialogue_popup_text h2,
.popup_title,
.dialogue_popup_controls h3 {
    color: var(--bl-text-1);
}

/* ---------- 提示消息 ---------- */
#toast-container > div {
    background-color: var(--bl-bg-1);
    border: 1px solid var(--bl-line);
    border-left: 3px solid var(--bl-blue);
    border-radius: var(--bl-radius-sm);
    box-shadow: var(--bl-shadow-float);
    color: var(--bl-text-1);
    opacity: 1;
}

#toast-container > .toast-success {
    border-left-color: var(--bl-pink);
}

#toast-container > .toast-error {
    border-left-color: #F56C6C;
}

#toast-container > .toast-warning {
    border-left-color: #FFB800;
}

/* ---------- 加载与欢迎页 ---------- */
#loading_mes,
#loader {
    color: var(--bl-text-2);
}

#welcomePanel,
.welcomePanel {
    background-color: var(--bl-bg-1);
    border-radius: var(--bl-radius);
}

/* ---------- 酒馆的深色默认值（浅色主题下会糊成一片） ---------- */

/* 设置面板的分组标题：默认拿 SmartThemeQuoteColor 做深灰渐变，白底上像一条黑带 */
#user-settings-block h4,
.standoutHeader,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header {
    background-image: none;
    background-color: var(--bl-bg-2);
    border: 1px solid var(--bl-line);
    border-radius: var(--bl-radius-sm);
    color: var(--bl-text-1);
}

#user-settings-block h4:hover,
.standoutHeader:hover,
#extensions_settings .inline-drawer-toggle.inline-drawer-header:hover,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header:hover {
    filter: none;
    background-color: var(--bl-pink-soft);
    color: var(--bl-text-1);
}

/*
 * 提示词管理器：类名带 completion_ 前缀（聊天补全）和不带前缀（文本补全）两套，
 * 用 [class*=] 一次覆盖；酒馆自己的规则是 #id #id 级别，这里必须 !important 才压得住。
 */
[class*="prompt_manager_prompt"] [class*="prompt_manager_prompt_name"],
[class*="prompt_manager_prompt_name"] .prompt-manager-inspect-action {
    color: var(--bl-text-1) !important;
}

/* 启用中的开关用品牌粉 */
[class*="prompt_manager_prompt"]:not([class*="prompt_manager_prompt_disabled"]) .prompt-manager-toggle-action {
    color: var(--bl-pink) !important;
}

/* 禁用项名称酒馆默认用 white30a（深色主题专用），白底上等于隐形 */
[class*="prompt_manager_prompt_disabled"] {
    border-color: var(--bl-line) !important;
    background-color: var(--bl-bg-2);
}

[class*="prompt_manager_prompt_disabled"] [class*="prompt_manager_prompt_name"],
[class*="prompt_manager_prompt_disabled"] [class*="prompt_manager_prompt_name"] .prompt-manager-inspect-action {
    color: var(--bl-text-3) !important;
}

/* 表头「名称 / Token」那行同样是 white50a */
[class*="prompt_manager_header"] {
    color: var(--bl-text-3) !important;
}

/* 图标上的黑色投影是给深色底做的，浅底上去掉更干净 */
[class*="prompt_manager_prompt"] span span span,
[class*="prompt_manager_header_advanced"] span {
    filter: none;
}

/* 选中态：酒馆默认拿 SmartThemeQuoteColor 铺深色块（连着浮点数还用深红），统一改粉色浅底 */
.macroBrowser .macro-sort-btn.active,
.macroBrowser .macro-item.selected,
#rm_print_characters_block.group_overlay_mode_select .character_select.character_selected,
#bg_tabs .bg_tabs_list .bg_tab_button.ui-tabs-active {
    background-color: var(--bl-pink-soft);
    color: var(--bl-text-1);
}

#chat .mes.selected {
    background-color: var(--bl-pink-soft);
}

/* ---------- 标签 / 徽章 ---------- */
.tag,
.tag_name,
.character_version,
.character_tag {
    border-radius: var(--bl-radius-pill);
    background-color: var(--bl-bg-3);
    color: var(--bl-text-2);
    border: none;
}

.tag:hover,
.character_tag:hover {
    background-color: var(--bl-pink-soft);
    color: var(--bl-pink);
}


/*
 * 主页（欢迎面板）：按 B 站专栏首页的思路重排——
 * 页头（logo + 版本 + 工具按钮）→ 分类标签行（最近聊天 + 快捷入口）→ 卡片流。
 *
 * 卡片用酒馆 1.19 的「最近聊天」组件：
 *   .recentChat > .avatar + .recentChatInfo
 *   .recentChatInfo > .chatNameContainer(.chatName/.chatDate/.chatActions)
 *                   + .chatMessageContainer(.chatMessage/.chatStats)
 * 用 display: contents 把两个容器摊平到同一网格，凑出「标题 / 摘要 / 元信息」三层。
 *
 * 注意：酒馆自带的 welcome.css 用的是 `.welcomeRecent .recentChatList .recentChat …`（三到四级类），
 * 所以这里统一加 `.welcomePanel` 前缀压过它，不要简化选择器。
 */

/* ---------- 页头 ---------- */
.welcomePanel {
    background-color: transparent;
    border: none;
    border-radius: 0;
    box-shadow: none;
    padding: 0;
}

.welcomePanel .welcomeHeaderTitle {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 2px 12px;
    border-bottom: 1px solid var(--bl-line);
}

.welcomePanel .welcomeHeaderLogo {
    width: 26px;
    height: 26px;
    border-radius: 6px;
    flex: 0 0 auto;
}

.welcomePanel .welcomeHeaderVersionDisplay {
    font-size: 17px;
    font-weight: 600;
    color: var(--bl-text-1);
    letter-spacing: 0;
}

.welcomePanel .welcomeHeaderTitle .mes_button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 30px;
    height: 30px;
    margin-left: 2px;
    border-radius: 50%;
    color: var(--bl-text-3);
    opacity: 0.75;
    transition: background-color var(--bl-ease), color var(--bl-ease), opacity var(--bl-ease);
}

.welcomePanel .welcomeHeaderTitle .mes_button:hover {
    background-color: var(--bl-pink-soft);
    color: var(--bl-pink);
    opacity: 1;
}

/* ---------- 分类标签行 ---------- */
.welcomePanel .welcomeHeader {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
    padding: 14px 2px 10px;
    font-size: 15px;
    font-weight: 600;
    color: var(--bl-text-1);
}

/* 「最近的聊天」前面的粉色小竖条 */
.welcomePanel .welcomeHeader::before {
    content: "";
    flex: 0 0 auto;
    width: 3px;
    height: 15px;
    border-radius: 2px;
    background-color: var(--bl-pink);
}

.welcomePanel .welcomeShortcuts {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-left: auto;
}

.welcomePanel .welcomeShortcuts .menu_button {
    height: 26px;
    padding: 0 11px;
    border: none;
    border-radius: var(--bl-radius-pill);
    background-color: var(--bl-bg-2);
    color: var(--bl-text-2);
    font-size: 12px;
    font-weight: 500;
    transition: background-color var(--bl-ease), color var(--bl-ease);
}

.welcomePanel .welcomeShortcuts .menu_button:hover {
    background-color: var(--bl-pink-soft);
    color: var(--bl-pink);
}

.welcomePanel .welcomeShortcutsSeparator {
    display: none;
}

/* ---------- 卡片流 ---------- */
.welcomePanel .welcomeRecent {
    padding: 2px 0 6px;
}

.welcomePanel .welcomeRecent .recentChatList {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.welcomePanel .welcomeRecent .recentChatList .recentChat {
    position: relative;
    display: grid;
    grid-template-columns: 56px minmax(0, 1fr);
    column-gap: 12px;
    align-items: start;
    padding: 12px 14px;
    border: 1px solid var(--bl-line);
    border-radius: var(--bl-radius);
    background-color: var(--bl-bg-1);
    transition: border-color var(--bl-ease), box-shadow var(--bl-ease), transform var(--bl-ease);
}

/* 折叠的卡片必须真的不占位，否则「更多」按钮前会留一大片空白 */
.welcomePanel .welcomeRecent .recentChatList .recentChat.hidden {
    display: none;
}

.welcomePanel .welcomeRecent .recentChatList .recentChat:hover {
    background-color: var(--bl-bg-1);
    border-color: var(--bl-pink);
    box-shadow: 0 4px 14px rgba(251, 114, 153, 0.16);
    transform: translateY(-1px);
}

.welcomePanel .welcomeRecent .recentChatList .recentChat:focus-within {
    border-color: var(--bl-pink);
    box-shadow: 0 0 0 2px rgba(251, 114, 153, 0.16);
}

/* 封面 = 角色头像，裁成圆角方块 */
.welcomePanel .welcomeRecent .recentChatList .recentChat .avatar {
    flex: 0 0 auto;
    align-self: start;
    width: 56px;
    height: 56px;
    margin: 0;
    border-radius: 8px;
    overflow: hidden;
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .avatar img {
    display: block;
    width: 100%;
    height: 100%;
    border-radius: 8px;
    object-fit: cover;
}

/* 右侧内容摊平成三层：标题 / 摘要 / 元信息 */
.welcomePanel .welcomeRecent .recentChatList .recentChat .recentChatInfo {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-areas:
        "name name"
        "preview preview"
        "date stats";
    align-items: center;
    align-self: start;
    gap: 3px 10px;
    min-width: 0;
    overflow: visible;
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatNameContainer,
.welcomePanel .welcomeRecent .recentChatList .recentChat .chatMessageContainer {
    display: contents;
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatName {
    grid-area: name;
    flex: none;
    min-width: 0;
    padding-right: 84px; /* 给右上角的置顶/重命名/删除让位 */
    font-size: 15px;
    font-weight: 600;
    line-height: 1.45;
    color: var(--bl-text-1);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatName .characterName {
    font-weight: 700;
    color: var(--bl-text-1);
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatName > span {
    font-size: 13px;
    font-weight: 400;
    color: var(--bl-text-3);
}

/* 摘要，两行截断 */
.welcomePanel .welcomeRecent .recentChatList .recentChat .chatMessage {
    grid-area: preview;
    font-size: 13px;
    line-height: 1.55;
    color: var(--bl-text-3);
    word-break: break-word;
}

/* 元信息行：左时间、右数据 */
.welcomePanel .welcomeRecent .recentChatList .recentChat .chatDate {
    grid-area: date;
    justify-self: start;
    margin: 0;
    font-size: 12px;
    color: var(--bl-text-3);
    white-space: nowrap;
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatStats {
    grid-area: stats;
    justify-self: end;
    align-self: center;
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 12px;
    color: var(--bl-text-3);
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatStats .counterBlock {
    display: inline-flex;
    align-items: center;
    gap: 4px;
}

/* 酒馆在条数和大小之间插了个竖线，这里换成分隔点 */
.welcomePanel .welcomeRecent .recentChatList .recentChat .chatStats .counterBlock::after {
    content: "·";
    margin-left: 4px;
    color: var(--bl-text-3);
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatStats small {
    font-size: 12px;
    color: var(--bl-text-3);
}

/* 操作按钮：平时隐形，悬停/聚焦才出现 */
.welcomePanel .welcomeRecent .recentChatList .recentChat .chatActions {
    position: absolute;
    top: 9px;
    right: 10px;
    display: flex;
    gap: 4px;
    opacity: 0;
    transition: opacity var(--bl-ease);
}

.welcomePanel .welcomeRecent .recentChatList .recentChat:hover .chatActions,
.welcomePanel .welcomeRecent .recentChatList .recentChat:focus-within .chatActions {
    opacity: 1;
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatActions button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    margin: 0;
    padding: 0;
    border: none;
    border-radius: 50%;
    background-color: transparent;
    color: var(--bl-text-3);
    font-size: 12px;
    transition: background-color var(--bl-ease), color var(--bl-ease);
}

.welcomePanel .welcomeRecent .recentChatList .recentChat .chatActions button:hover {
    background-color: var(--bl-pink-soft);
    color: var(--bl-pink);
}

/* 「显示更多」：做成一个居中的圆形小按钮，紧贴最后一张卡片 */
.welcomePanel .welcomeRecent .recentChatList .showMoreChats {
    align-self: center;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    margin: 0;
    padding: 0;
    border: 1px solid transparent;
    border-radius: 50%;
    background-color: var(--bl-bg-2);
    color: var(--bl-text-3);
    transition: background-color var(--bl-ease), color var(--bl-ease);
}

.welcomePanel .welcomeRecent .recentChatList .showMoreChats:hover {
    background-color: var(--bl-pink-soft);
    color: var(--bl-pink);
}

/* 置顶标记换成粉色小三角 */
.welcomePanel .welcomeRecent .recentChatList .recentChat .recentChatPinned {
    top: 2px;
    left: 2px;
    color: var(--bl-pink);
    opacity: 1;
}

/* 触屏没有 hover，按钮常显 */
@media (hover: none) {
    .welcomePanel .welcomeRecent .recentChatList .recentChat .chatActions {
        opacity: 1;
    }
}

/* ---------- 小屏 ---------- */
@media (max-width: 640px) {
    .welcomePanel .welcomeRecent .recentChatList .recentChat {
        grid-template-columns: 46px minmax(0, 1fr);
        column-gap: 10px;
        padding: 10px 12px;
    }

    .welcomePanel .welcomeRecent .recentChatList .recentChat .avatar {
        width: 46px;
        height: 46px;
        border-radius: 7px;
    }

    .welcomePanel .welcomeRecent .recentChatList .recentChat .avatar img {
        border-radius: 7px;
    }

    .welcomePanel .welcomeRecent .recentChatList .recentChat .chatName {
        font-size: 14px;
        padding-right: 0;
    }

    .welcomePanel .welcomeHeader {
        font-size: 14px;
    }

    .welcomePanel .welcomeShortcuts .menu_button {
        height: 24px;
        padding: 0 9px;
        font-size: 11px;
    }
}


/*
 * 加载页：完全接管 SillyTavern 的加载遮罩
 *
 * 两条链路都要覆盖，否则切换时会闪一下默认样式：
 *   1. HTML 首屏的 <div id="preloader">（JS 还没跑起来时）
 *   2. 初始化后由 action-loader.js 创建的
 *      <dialog class="popup transparent_dialogue_popup"> 内的 #loader.splash-screen
 *
 * 方法参考「Word 文档 V2.1」主题的「13 / 加载页」：遮罩铺满全屏、隐藏原生
 * SillyTavern logo、把 #loader 重排成居中卡片，::before 写标题、::after 做进度条，
 * 副文案沿用酒馆自带的 .splash-message（保留多语言）。
 */

/*
 * 品牌标识尺寸：盒子宽度按「小电视 + 间距 + 字标」精确计算，
 * 这样 flex 居中时视觉内容才真正居中（背景图左对齐拼在过宽的盒子里会偏左）。
 * 2.1876 = wordmark.svg 的宽高比 2186.86 / 999.65。
 */
#preloader::before,
#loader #load-spinner {
    --bl-brand-tv: 40px;
    --bl-brand-mark-h: 34px;
    --bl-brand-gap: 10px;
    --bl-brand-mark-w: calc(var(--bl-brand-mark-h) * 2.1876);
    --bl-brand-w: calc(var(--bl-brand-tv) + var(--bl-brand-gap) + var(--bl-brand-mark-w));
}

/* ---------- 全屏遮罩 ---------- */
#preloader,
.popup.transparent_dialogue_popup:has(#loader) {
    background-color: var(--bl-bg-2);
    background-image:
        radial-gradient(circle at 50% 34%, rgba(251, 114, 153, 0.16), transparent 58%),
        radial-gradient(circle at 50% 66%, rgba(0, 174, 236, 0.12), transparent 52%);
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
}

/* 首屏还没创建 #loader 时，至少先给出品牌标识 */
#preloader::before {
    content: "";
    position: absolute;
    left: 50%;
    top: 50%;
    width: var(--bl-brand-w);
    height: var(--bl-brand-tv);
    transform: translate(-50%, -50%);
    background-image: var(--bl-tv), var(--bl-wordmark);
    background-repeat: no-repeat, no-repeat;
    background-position: left center, calc(var(--bl-brand-tv) + var(--bl-brand-gap)) center;
    background-size: auto var(--bl-brand-tv), auto var(--bl-brand-mark-h);
    filter: drop-shadow(0 4px 10px rgba(0, 174, 236, 0.18));
}

/* 加载 Popup 本身：铺满视口、去掉弹窗边框与内边距 */
.popup.transparent_dialogue_popup:has(#loader) {
    position: fixed !important;
    inset: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    width: 100dvw !important;
    height: 100dvh !important;
    max-width: none !important;
    max-height: none !important;
    margin: 0 !important;
    padding: 0 !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    overflow: hidden !important;
}

.popup:has(#loader) :is(.popup-body, .popup-content) {
    width: 100%;
    height: 100%;
    max-height: none;
    margin: 0;
    padding: 0;
    overflow: hidden;
}

/* ---------- 居中卡片 ---------- */
#loader {
    position: fixed !important;
    inset: auto !important;
    left: 50% !important;
    top: 50% !important;
    transform: translate(-50%, -50%);
    /* loader.css 的 #loader.splash-screen 有 width:100%，特异性更高，必须压过去 */
    width: min(400px, 88vw) !important;
    height: auto !important;
    max-height: none !important;
    margin: 0 !important;
    padding: 38px 28px 34px;
    display: flex !important;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    /* loader.css 里 #loader.splash-screen 有 gap: 4rem，必须压掉 */
    gap: 0 !important;
    border: 1px solid var(--bl-line);
    border-radius: 16px;
    background:
        linear-gradient(90deg, var(--bl-pink), var(--bl-blue)) top left / 100% 3px no-repeat,
        var(--bl-bg-1);
    box-shadow: 0 18px 48px rgba(0, 161, 214, 0.14), 0 4px 12px rgba(24, 25, 28, 0.05);
    color: var(--bl-text-1);
    font-family: var(--bl-font);
    overflow: hidden;
}

/* 酒馆自带的 SillyTavern logo 不要 */
#loader .splash-logo {
    display: none !important;
}

/* 小电视 + bilibili 字标，沿用顶栏那套矢量素材 */
#loader #load-spinner {
    position: relative !important;
    top: auto !important;
    left: auto !important;
    order: 1;
    width: var(--bl-brand-w) !important;
    height: var(--bl-brand-tv) !important;
    margin: 0 0 22px;
    /* 关掉 Font Awesome 齿轮字形与自带旋转 */
    font-size: 0 !important;
    color: transparent !important;
    animation: bl-loader-float 2.4s ease-in-out infinite;
    background-image: var(--bl-tv), var(--bl-wordmark);
    background-repeat: no-repeat, no-repeat;
    background-position: left center, calc(var(--bl-brand-tv) + var(--bl-brand-gap)) center;
    background-size: auto var(--bl-brand-tv), auto var(--bl-brand-mark-h);
    filter: drop-shadow(0 4px 10px rgba(0, 174, 236, 0.18));
}

#loader #load-spinner::before,
#loader #load-spinner::after {
    content: none !important;
}

/* 主标题 */
#loader::before {
    content: "bilibili 专栏";
    order: 2;
    color: var(--bl-text-1);
    font: 600 20px/1.4 var(--bl-font);
    letter-spacing: 0.02em;
}

/* 加载文案：沿用酒馆原生文案，只统一字体与颜色 */
#loader .splash-message {
    order: 3;
    margin: 8px 0 0;
    color: var(--bl-text-3);
    font: 400 13px/1.6 var(--bl-font) !important;
    letter-spacing: 0.04em;
    opacity: 1;
}

/* 粉蓝流动进度条 */
#loader::after {
    content: "";
    order: 4;
    width: 168px;
    height: 4px;
    margin-top: 24px;
    border-radius: var(--bl-radius-pill);
    background: linear-gradient(90deg, var(--bl-pink), var(--bl-blue), var(--bl-pink));
    background-size: 200% 100%;
    animation: bl-loader-bar 1.6s linear infinite;
}

@keyframes bl-loader-bar {
    from {
        background-position: 200% 0;
    }
    to {
        background-position: -200% 0;
    }
}

@keyframes bl-loader-float {
    0%, 100% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-5px);
    }
}

/* 尊重系统「减少动态效果」 */
@media (prefers-reduced-motion: reduce) {
    #loader #load-spinner,
    #loader::after {
        animation: none !important;
    }
}

/* 窄屏下收一圈 */
@media (max-width: 640px) {
    #loader {
        width: min(340px, 88vw) !important;
        padding: 30px 22px 28px;
    }

    /* 只需要改两个尺寸，盒子宽度会按同一组变量自动重算 */
    #loader #load-spinner,
    #preloader::before {
        --bl-brand-tv: 36px;
        --bl-brand-mark-h: 30px;
    }

    #loader::after {
        width: 148px;
    }
}


/*
 * 适配层：窄屏与移动端
 * 收边距、降字号、保证触摸目标，正文不撑破布局。
 */

@media (max-width: 640px) {
    :root {
        --bl-title-size: 19px;
        --bl-body-size: 15.5px;
        --bl-body-line: 1.8;
        --bl-comment-size: 14.5px;
        --bl-avatar-size: 38px;
        --bl-chat-gap: 10px;
    }

    #chat .mes[is_user="false"] {
        padding: 16px 16px 8px;
        border-radius: var(--bl-radius-sm);
        gap: 10px;
    }

    #chat .mes[is_user="true"] {
        padding: 12px 14px 8px;
        border-radius: var(--bl-radius-sm);
    }

    #chat .mes[is_user="true"] .mesAvatarWrapper {
        flex-basis: 32px;
        width: 32px;
    }

    #chat .mes[is_user="true"] .mesAvatarWrapper .avatar {
        width: 32px;
        height: 32px;
    }

    /* 右侧镜像占位跟着头像一起缩小，保持左右对称 */
    #chat .mes[is_user="true"]::after {
        flex-basis: 46px;
    }

    #form_sheld {
        padding: 8px 8px 10px;
    }

    #nonQRFormItems {
        padding: 4px 6px;
    }

    /* 触摸目标放大到 40px 以上 */
    #send_but:not(.displayNone),
    #mes_stop:not(.displayNone),
    #mes_continue:not(.displayNone) {
        width: 32px;
        height: 32px;
    }

    #options_button,
    #leftSendForm .interactable {
        width: 32px;
        height: 32px;
    }
}

@media (max-width: 500px) {
    #chat .mes_text,
    #chat .mes[is_user="false"] .mes_text {
        --bl-body-line: 1.75;
    }

    /* 专栏底部三连行缩一号，避免换行 */
    #chat .mes[is_user="false"] .mes_block::after {
        font-size: 15px;
        letter-spacing: 0;
        margin-top: 10px;
        padding-top: 8px;
    }

    #chat .mes .swipes-counter {
        font-size: 10px;
    }

    /* 小屏用紧凑版标识，给顶栏图标让位 */
    #top-settings-holder {
        padding: 0 64px 0 84px;
    }

    #top-settings-holder::before {
        left: 10px;
        width: 74px;
        height: 26px;
        background-position: left center, 30px center;
        background-size: auto 22px, auto 19px;
    }

    #rightNavHolder > .drawer-toggle {
        right: 10px;
    }

    #rightNavDrawerIcon {
        height: 26px;
        padding: 0 10px;
    }

    #rightNavDrawerIcon::after {
        font-size: 12px;
        letter-spacing: 0;
    }
}

/* 中等宽度：「投稿」按钮缩一号，右侧留白同步收窄 */
@media (min-width: 501px) and (max-width: 900px) {
    #top-settings-holder {
        padding: 0 78px 0 116px;
    }

    #rightNavHolder > .drawer-toggle {
        right: 12px;
    }

    #rightNavDrawerIcon {
        height: 28px;
        padding: 0 12px;
    }

    #rightNavDrawerIcon::after {
        font-size: 13px;
    }
}

/* 尊重系统「减少动态效果」 */
@media (prefers-reduced-motion: reduce) {
    #chat .mes[is_user="false"] .mesAvatarWrapper .avatar:hover,
    #send_but:not(.displayNone):hover,
    #mes_stop:not(.displayNone):hover {
        transform: none;
    }
}
